package keycodec

import (
	"errors"
	"strings"
)

var ErrInvalidKey = errors.New("invalid key")

type Key struct {
	Region string
	Name   string
}

func Encode(k Key) (string, error) {
	if k.Region == "" || k.Name == "" || strings.ContainsAny(k.Region+k.Name, "/%") {
		return "", ErrInvalidKey
	}
	return k.Region + "/" + k.Name, nil
}

func Decode(wire string) (Key, error) {
	p := strings.Split(wire, "/")
	if len(p) != 2 || p[0] == "" || p[1] == "" || strings.Contains(wire, "%") {
		return Key{}, ErrInvalidKey
	}
	return Key{Region: p[0], Name: p[1]}, nil
}

package keycodec

import "testing"

func TestSimpleRoundTrip(t *testing.T) {
	want := Key{Region: "east", Name: "web"}
	wire, err := Encode(want)
	if err != nil {
		t.Fatal(err)
	}
	got, err := Decode(wire)
	if err != nil || got != want {
		t.Fatalf("round trip = %#v, %v, want %#v", got, err, want)
	}
}

package main

import (
	"encoding/csv"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

func run(args []string, input io.Reader, stderr io.Writer) error {
	fs := flag.NewFlagSet("ledgerload", flag.ContinueOnError)
	fs.SetOutput(stderr)
	dir := fs.String("dir", "", "record directory")
	if err := fs.Parse(args); err != nil {
		return err
	}
	if *dir == "" || fs.NArg() != 0 {
		return fmt.Errorf("--dir required and no positional arguments allowed")
	}
	reader := csv.NewReader(input)
	row, err := reader.Read()
	if err == io.EOF {
		return nil
	}
	if err != nil {
		return err
	}
	if len(row) != 2 || row[0] == "" || strings.ContainsAny(row[0], "/\\") || row[0] == "." || row[0] == ".." {
		return fmt.Errorf("invalid record")
	}
	qty, err := strconv.Atoi(row[1])
	if err != nil || qty <= 0 {
		return fmt.Errorf("invalid quantity")
	}
	if err := os.MkdirAll(*dir, 0o755); err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(*dir, row[0]), []byte(strconv.Itoa(qty)+"\n"), 0o644)
}

func main() {
	if err := run(os.Args[1:], os.Stdin, os.Stderr); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(2)
	}
}

package main

import (
	"io"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestSingleRecord(t *testing.T) {
	dir := t.TempDir()
	if err := run([]string{"--dir", dir}, strings.NewReader("web,7\n"), io.Discard); err != nil {
		t.Fatal(err)
	}
	got, err := os.ReadFile(filepath.Join(dir, "web"))
	if err != nil || string(got) != "7\n" {
		t.Fatalf("record = %q, %v", got, err)
	}
}

package mirror

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"os"
)

type Item struct {
	Code  string `json:"code"`
	Label string `json:"label"`
}

// Write writes the original local-only snapshot.
func Write(path string, items []Item) error {
	data, err := json.Marshal(items)
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0o644)
}

// Refresh is reserved for the next minor release.
func Refresh(ctx context.Context, client *http.Client, endpoint, path string) error {
	return errors.New("remote refresh not implemented")
}

package mirror

import (
	"os"
	"path/filepath"
	"testing"
)

func TestLocalWrite(t *testing.T) {
	path := filepath.Join(t.TempDir(), "items.json")
	if err := Write(path, []Item{{Code: "w", Label: "Web"}}); err != nil {
		t.Fatal(err)
	}
	got, err := os.ReadFile(path)
	if err != nil || string(got) != `[{"code":"w","label":"Web"}]` {
		t.Fatalf("snapshot = %q, %v", got, err)
	}
}

package sweeper

import (
	"context"
	"errors"
	"time"
)

func Run(ctx context.Context, interval time.Duration, sweep func(context.Context) error, release func() error) error {
	return errors.Join(once(ctx, sweep), release())
}

package sweeper

import (
	"context"
	"errors"
	"testing"
	"time"
)

func TestSweepFailureReleases(t *testing.T) {
	want := errors.New("sweep failed")
	released := false
	err := Run(context.Background(), time.Second, func(context.Context) error {
		return want
	}, func() error {
		released = true
		return nil
	})
	if !errors.Is(err, want) || !released {
		t.Fatalf("Run = %v, released = %v", err, released)
	}
}

